import math

d_model = 512
pos = 7

def pe(pos, i, d_model):
    angle = pos / (10000 ** (2 * i / d_model))
    return math.sin(angle) if i % 2 == 0 else math.cos(angle)

for i in range(4):
    print(f'component {i}: {pe(pos, i, d_model): .4f}')
# Different i give different frequencies: i=0 encodes coarse
# position, larger i encode fine-grained position
